        >
            {label}
        </Tabs.Trigger>
    )

    return (
        <Dialog.Root open={open} onOpenChange={onOpenChange}>
            <Dialog.Portal>
                <Dialog.Overlay className="fixed inset-0 bg-slate-900/40 backdrop-blur-md z-[60] transition-opacity animate-in fade-in duration-300" />
                <Dialog.Content className="fixed left-[50%] top-[50%] translate-x-[-50%] translate-y-[-50%] w-full max-w-4xl max-h-[90vh] bg-white rounded-2xl shadow-2xl z-[70] flex flex-col outline-none transform transition-all animate-in fade-in zoom-in-95 duration-300 overflow-hidden">

                    {/* Premium Header */}
                    <div className="flex items-center justify-between p-6 bg-slate-50/50 border-b border-slate-100">
                        <div className="flex flex-col">
                            <Dialog.Title className="text-xl font-bold text-primary-navy">
                                {_productId ? 'Ürünü Düzenle' : 'Yeni Ürün Ekle'}
                            </Dialog.Title>
                            <p className="text-xs text-slate-500 mt-0.5">VentHub Katalog Yönetim Sistemi</p>
                        </div>
                        <Dialog.Close className="p-2 hover:bg-white hover:shadow-sm rounded-full text-slate-400 hover:text-primary-navy transition-all duration-200">
                            <X size={20} />
                        </Dialog.Close>
                    </div>

                    {/* Body */}
                    <div className="flex-1 overflow-y-auto">
                        {loading ? (
                            <div className="flex items-center justify-center h-64">
                                <Loader2 className="animate-spin text-blue-600" size={32} />
                            </div>
                        ) : (
                            <form id="product-form" onSubmit={handleSubmit(onSubmit)} className="p-6">
                                <Tabs.Root value={activeTab} onValueChange={setActiveTab}>
                                    <Tabs.List className="flex border-b border-gray-200 mb-6 overflow-x-auto">
                                        <TabTrigger value="info" label="Genel Bilgiler" />
                                        <TabTrigger value="pricing" label="Fiyat & Stok" />
                                        <TabTrigger value="images" label="Görseller" />
                                        <TabTrigger value="specs" label="Teknik Özellikler" />
                                        <TabTrigger value="seo" label="SEO" />
                                    </Tabs.List>

                                    {/* INFO TAB */}
                                    <Tabs.Content value="info" className="space-y-4">
                                        <div className="grid grid-cols-2 gap-4">
                                            <div className="space-y-2">
                                                <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">Ürün Adı *</label>
                                                <input {...register('name')} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all" />
                                                {errors.name && <span className="text-xs text-red-500">{errors.name.message}</span>}
                                            </div>
                                            <div className="space-y-2 text-right">
                                                <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">SKU (Stok Kodu) *</label>
                                                <input {...register('sku')} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all" />
                                                {errors.sku && <span className="text-xs text-red-500">{errors.sku.message}</span>}
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">Marka</label>
                                                <input {...register('brand')} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all" />
                                            </div>
                                            <div className="space-y-2 text-right">
                                                <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">Model Kodu</label>
                                                <input {...register('model_code')} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all" />
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">Kategori</label>
                                                <select {...register('category_id')} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all appearance-none cursor-pointer">
                                                    <option value="">Seçiniz</option>
                                                    {categories.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
                                                </select>
                                            </div>
                                            <div className="space-y-2 text-right">
                                                <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">Durum</label>
                                                <select {...register('status')} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all appearance-none cursor-pointer">
                                                    <option value="active">Aktif</option>
                                                    <option value="inactive">Pasif</option>
                                                    <option value="out_of_stock">Stok Yok</option>
                                                </select>
                                            </div>
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">Açıklama</label>
                                            <textarea {...register('description')} rows={4} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all resize-none" />
                                        </div>
                                        <div className="flex items-center gap-2">
                                            <input type="checkbox" {...register('is_featured')} id="is_featured" className="rounded border-gray-300 text-blue-600 focus:ring-blue-500" />
                                            <label htmlFor="is_featured" className="text-sm font-medium text-gray-700">Öne Çıkan Ürün</label>
                                        </div>
                                    </Tabs.Content>

                                    {/* PRICING TAB */}
                                    <Tabs.Content value="pricing" className="space-y-4">
                                        <div className="grid grid-cols-2 gap-4">
                                            <div className="space-y-2">
                                                <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">Satış Fiyatı (TL)</label>
                                                <input type="number" step="0.01" {...register('price', { valueAsNumber: true })} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all font-semibold text-slate-900" />
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">Alış Fiyatı (TL)</label>
                                                <input type="number" step="0.01" {...register('purchase_price', { valueAsNumber: true })} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all font-semibold text-slate-600" />
                                            </div>
                                            <div className="space-y-2">
                                                <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">Stok Adedi</label>
                                                <input type="number" {...register('stock_qty', { valueAsNumber: true })} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all font-bold text-slate-900" />
                                            </div>
                                            <div className="space-y-2 text-right">
                                                <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">Kritik Stok Seviyesi</label>
                                                <input type="number" {...register('low_stock_threshold', { valueAsNumber: true })} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all font-bold text-rose-600" />
                                            </div>
                                        </div>
                                    </Tabs.Content>

                                    {/* IMAGES TAB */}
                                    <Tabs.Content value="images" className="space-y-4">
                                        <div className="border-2 border-dashed border-gray-300 rounded-xl p-8 flex flex-col items-center justify-center text-gray-500 hover:border-blue-500 hover:bg-blue-50 transition-colors cursor-pointer relative">
                                            <input type="file" multiple accept="image/*" onChange={handleImageSelect} className="absolute inset-0 w-full h-full opacity-0 cursor-pointer" />
                                            <Upload size={32} className="mb-2" />
                                            <p className="text-sm font-medium">Resimleri buraya sürükleyin veya seçin</p>
                                            <p className="text-xs text-gray-400 mt-1">Otomatik WebP sıkıştırma uygulanır</p>
                                        </div>

                                        <div className="grid grid-cols-4 gap-4 mt-4">
                                            {images.map((img, idx) => (
                                                <div key={idx} className="relative group border rounded-lg overflow-hidden aspect-square bg-gray-50">
                                                    <VentImage src={img.url} alt="Product" className="w-full h-full object-contain"  />
                                                    <button
                                                        type="button"
                                                        onClick={() => removeImage(idx)}
                                                        className="absolute top-2 right-2 bg-red-500 text-white p-1.5 rounded-full opacity-0 group-hover:opacity-100 transition-opacity"
                                                    >
                                                        <Trash2 size={16} />
                                                    </button>
                                                    {idx === 0 && (
                                                        <div className="absolute bottom-0 inset-x-0 bg-blue-600 text-white text-[10px] py-1 text-center">
                                                            Kapak Görseli
                                                        </div>
                                                    )}
                                                </div>
                                            ))}
                                        </div>
                                    </Tabs.Content>

                                    {/* SPECS TAB */}
                                    <Tabs.Content value="specs" className="space-y-4">
                                        <div className="flex justify-between items-center mb-2">
                                            <h3 className="text-sm font-medium text-gray-700">Teknik Özellikler (JSON)</h3>
                                            <button type="button" onClick={addSpec} className="text-blue-600 text-sm flex items-center gap-1 hover:underline">
                                                <Plus size={16} /> Özellik Ekle
                                            </button>
                                        </div>

                                        <div className="space-y-2">
                                            {specs.map((spec, idx) => (
                                                <div key={idx} className="flex gap-2 items-center">
                                                    <input
                                                        placeholder="Özellik Adı (örn. Güç)"
                                                        value={spec.key}
                                                        onChange={(e) => handleSpecChange(idx, 'key', e.target.value)}
                                                        className="flex-1 border rounded px-3 py-2 text-sm"
                                                    />
                                                    <input
                                                        placeholder="Değer (örn. 5kW)"
                                                        value={spec.value}
                                                        onChange={(e) => handleSpecChange(idx, 'value', e.target.value)}
                                                        className="flex-1 border rounded px-3 py-2 text-sm"
                                                    />
                                                    <button type="button" onClick={() => removeSpec(idx)} className="text-red-500 hover:bg-red-50 p-2 rounded">
                                                        <Trash2 size={16} />
                                                    </button>
                                                </div>
                                            ))}
                                            {specs.length === 0 && (
                                                <div className="text-center py-8 text-gray-400 text-sm border rounded-lg border-dashed">
                                                    Henüz teknik özellik eklenmemiş.
                                                </div>
                                            )}
                                        </div>
                                    </Tabs.Content>

                                    {/* SEO TAB */}
                                    <Tabs.Content value="seo" className="space-y-4">
                                        <div className="space-y-2">
                                            <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">SEO URL (Slug)</label>
                                            <input {...register('slug')} placeholder="Otomatik oluşturulur" className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm font-mono focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all" />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">Meta Başlık</label>
                                            <input {...register('meta_title')} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all" />
                                        </div>
                                        <div className="space-y-2">
                                            <label className="text-xs font-bold text-slate-500 uppercase tracking-tight">Meta Açıklama</label>
                                            <textarea {...register('meta_description')} rows={3} className="w-full bg-slate-50 border border-slate-200 rounded-lg px-4 py-2.5 text-sm focus:outline-none focus:ring-2 focus:ring-primary-navy/10 focus:border-primary-navy transition-all resize-none" />
                                        </div>
                                    </Tabs.Content>
                                </Tabs.Root>
                            </form>
                        )}
                    </div>

                    {/* Footer */}
                    <div className="p-6 bg-slate-50/80 border-t border-slate-100 flex justify-end gap-3 backdrop-blur-sm">
                        <button
                            type="button"
                            onClick={() => onOpenChange(false)}
                            className="px-6 py-2.5 text-sm font-bold text-slate-600 hover:bg-white hover:shadow-sm rounded-xl transition-all duration-200"
                        >
                            İptal
                        </button>
                        <button
                            type="submit"
                            form="product-form"
                            disabled={loading || uploading}
                            className={`${adminButtonPrimaryClass} flex items-center gap-2 px-8 py-2.5 rounded-xl disabled:opacity-50 disabled:cursor-not-allowed shadow-lg shadow-primary-navy/10 transition-transform active:scale-95`}
                        >
                            {(loading || uploading) ? <Loader2 className="animate-spin" size={18} /> : <Save size={18} />}
                            {_productId ? 'Değişiklikleri Kaydet' : 'Ürünü Oluştur'}
                        </button>
                    </div>

                </Dialog.Content>
            </Dialog.Portal>
        </Dialog.Root>
    )
}

'use client';

import React from 'react';
import { 
  AuthorityContent, 
  HeroBlock as HeroBlockType, 
  SpecsBlock as SpecsBlockType,
  MediaBlock as MediaBlockType,
  RichTextBlock as RichTextBlockType,
  FeaturesGridBlock as FeaturesGridBlockType,
  ComparisonBlock as ComparisonBlockType,
  CtaBannerBlock as CtaBannerBlockType
} from '@/types/authority';
import { cn } from '@/lib/utils';
import VideoAuthority from './VideoAuthority';
import ThreeDAuthority from './ThreeDAuthority';
import TechnicalDrawingAuthority from './TechnicalDrawingAuthority';
import * as LucideIcons from 'lucide-react';

// --- YARDIMCI BİLEŞENLER ---

const IconRenderer = ({ name, className }: { name: string, className?: string }) => {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const Icon = (LucideIcons as unknown)[name.charAt(0).toUpperCase() + name.slice(1)] || LucideIcons.Zap;
  return <Icon className={className} />;
};

// --- BLOK BİLEŞENLERİ ---

const HeroBlock: React.FC<{ block: HeroBlockType }> = ({ block }) => (
  <section className={cn(
    "relative py-24 px-6 overflow-hidden",
    block.config?.fullWidth ? "w-full" : "max-w-7xl mx-auto rounded-3xl my-12",
    block.config?.theme === 'dark' ? "bg-slate-900 text-white" : "bg-white text-slate-900 border border-slate-100 shadow-xl"
  )}>
    <div className="relative z-10 max-w-4xl mx-auto text-center space-y-6">
       {block.content.eyebrow && (
         <span className="text-indigo-500 font-bold tracking-widest uppercase text-xs">
           {block.content.eyebrow}
         </span>
       )}
       <h2 className="text-4xl md:text-6xl font-black tracking-tight leading-tight">{block.content.title}</h2>
       {block.content.description && (
         <p className="text-lg opacity-80 leading-relaxed max-w-2xl mx-auto">{block.content.description}</p>
       )}
       {block.content.ctaLabel && (
         <div className="pt-4">
           <a 
             href={block.content.ctaLink || '#'} 
             className="inline-flex h-12 items-center justify-center rounded-full bg-indigo-600 px-8 text-sm font-bold text-white hover:bg-indigo-700 transition-colors"
           >
             {block.content.ctaLabel}
           </a>
         </div>
       )}
    </div>
    {block.content.imageUrl && (
      <div className="absolute inset-0 z-0 opacity-20 pointer-events-none">
        <img src={block.content.imageUrl} alt="" className="w-full h-full object-cover" />
      </div>
    )}
  </section>
);

const SpecsBlock: React.FC<{ block: SpecsBlockType }> = ({ block }) => (
  <div className="max-w-7xl mx-auto py-16 px-6">
    <div className="mb-12">
      <h3 className="text-3xl font-bold tracking-tight text-slate-900 mb-4">{block.content.title}</h3>
      {block.content.description && <p className="text-slate-500">{block.content.description}</p>}
    </div>
    <div className={cn(
      "grid gap-4",
      block.content.columns === 4 ? "grid-cols-1 md:grid-cols-2 lg:grid-cols-4" : 
      block.content.columns === 3 ? "grid-cols-1 md:grid-cols-3" : "grid-cols-1 md:grid-cols-2"
    )}>
      {block.content.rows?.map((row, i: number) => (
        <div key={i} className="p-6 rounded-2xl bg-white border border-slate-100 shadow-sm hover:shadow-md transition-shadow">
          <div className="text-sm font-medium text-slate-400 mb-1">{row.label}</div>
          <div className="text-2xl font-black text-slate-900">
            {row.value}
            {row.unit && <span className="text-sm font-bold text-slate-400 ml-1">{row.unit}</span>}
          </div>
        </div>
      ))}
    </div>
  </div>
);

const FeaturesGridBlock: React.FC<{ block: FeaturesGridBlockType }> = ({ block }) => (
    <div className="max-w-7xl mx-auto py-20 px-6">
        {block.content.title && (
            <h3 className="text-3xl font-black text-center mb-16 tracking-tight text-slate-900">{block.content.title}</h3>
        )}
        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
            {block.content.items.map((item, i) => (
                <div key={i} className="group p-8 rounded-3xl bg-slate-50 border border-slate-100 hover:bg-white hover:shadow-2xl hover:-translate-y-2 transition-all duration-500">
                    <div className="w-14 h-14 rounded-2xl bg-indigo-600 flex items-center justify-center text-white mb-6 shadow-lg shadow-indigo-200">
                        <IconRenderer name={item.icon} className="w-7 h-7" />
                    </div>
                    <h4 className="text-xl font-bold text-slate-900 mb-3">{item.title}</h4>
                    <p className="text-slate-500 leading-relaxed text-sm">{item.description}</p>
                </div>
            ))}
        </div>
    </div>
);

const ComparisonBlock: React.FC<{ block: ComparisonBlockType }> = ({ block }) => (
    <div className="max-w-7xl mx-auto py-24 px-6">
        {block.content.title && (
            <h3 className="text-3xl font-black text-center mb-16 tracking-tight text-slate-900">{block.content.title}</h3>
        )}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-1 px-4 md:px-0 bg-slate-100 rounded-[40px] overflow-hidden border-8 border-slate-100">
            <div className="relative aspect-video bg-white flex flex-col items-center justify-center p-8 text-center group">
                <span className="absolute top-6 left-6 px-4 py-1 rounded-full bg-slate-100 text-[10px] font-black uppercase tracking-widest text-slate-400">{block.content.leftLabel}</span>
                {block.content.leftImage ? (
                    <img src={block.content.leftImage} alt={block.content.leftLabel} className="w-full h-full object-contain" />
                ) : (
                    <LucideIcons.AlertCircle className="w-12 h-12 text-slate-200" />
                )}
            </div>
            <div className="relative aspect-video bg-indigo-600 flex flex-col items-center justify-center p-8 text-center group">
                <span className="absolute top-6 right-6 px-4 py-1 rounded-full bg-white/20 text-[10px] font-black uppercase tracking-widest text-white">{block.content.rightLabel}</span>
                {block.content.rightImage ? (
                    <img src={block.content.rightImage} alt={block.content.rightLabel} className="w-full h-full object-contain brightness-0 invert" />
                ) : (
                    <LucideIcons.CheckCircle2 className="w-12 h-12 text-white/20" />
                )}
                {block.content.differenceText && (
                    <div className="absolute bottom-6 left-1/2 -translate-x-1/2 bg-white px-6 py-2 rounded-2xl shadow-xl">
                        <span className="text-indigo-600 font-bold text-xs uppercase tracking-widest">{block.content.differenceText}</span>
                    </div>
                )}
            </div>
        </div>
    </div>
);

const CtaBannerBlock: React.FC<{ block: CtaBannerBlockType }> = ({ block }) => (
    <div className="max-w-7xl mx-auto py-12 px-6">
        <div className="relative rounded-[40px] bg-indigo-600 p-12 md:p-20 overflow-hidden text-center md:text-left flex flex-col md:flex-row items-center justify-between gap-12">
            <div className="relative z-10 max-w-2xl">
                <h3 className="text-3xl md:text-5xl font-black text-white mb-6 tracking-tight leading-tight">{block.content.title}</h3>
                <p className="text-indigo-100 text-lg md:text-xl font-medium opacity-80">{block.content.description}</p>
            </div>
            <div className="relative z-10 shrink-0">
                <a 
                    href={block.content.buttonLink} 
                    className="inline-flex h-16 items-center justify-center rounded-3xl bg-white px-10 text-lg font-black text-indigo-600 hover:bg-indigo-50 hover:scale-105 transition-all shadow-2xl shadow-black/20 active:scale-95"
                >
                    {block.content.buttonLabel}
                    <LucideIcons.ArrowRight className="ml-3 w-6 h-6" />
                </a>
            </div>
            {/* Background Accents */}
            <div className="absolute top-0 right-0 w-96 h-96 bg-white/5 rounded-full blur-3xl -mr-48 -mt-48" />
            <div className="absolute bottom-0 left-0 w-64 h-64 bg-black/10 rounded-full blur-3xl -ml-32 -mb-32" />
        </div>
    </div>
);

// --- RENDERER ANA BİLEŞEN ---

export const AuthorityRenderer: React.FC<{ content: AuthorityContent | null }> = ({ content }) => {
  if (!content || !Array.isArray(content) || content.length === 0) return null;

  return (
    <div className="authority-content-wrapper space-y-0 bg-white">
      {content.map((block) => {
        if (block.config?.isHidden) return null;

        switch (block.type) {
          case 'hero':
            return <HeroBlock key={block.id} block={block as HeroBlockType} />;
          
          case 'specs':
            return <SpecsBlock key={block.id} block={block as SpecsBlockType} />;

          case 'features-grid':
            return <FeaturesGridBlock key={block.id} block={block as FeaturesGridBlockType} />;

          case 'comparison':
            return <ComparisonBlock key={block.id} block={block as ComparisonBlockType} />;

          case 'cta-banner':
            return <CtaBannerBlock key={block.id} block={block as CtaBannerBlockType} />;
          
          case 'media': {
            const mediaBlock = block as MediaBlockType;
            return (
              <div key={mediaBlock.id} className={cn(
                "py-12 px-6",
                mediaBlock.config?.fullWidth ? "w-full" : "max-w-7xl mx-auto"
              )}>
                {mediaBlock.content.title && (
                  <h3 className="text-2xl font-bold text-slate-900 mb-8">{mediaBlock.content.title}</h3>
                )}
                <div className="rounded-3xl overflow-hidden bg-slate-50 border border-slate-200 shadow-2xl aspect-video relative group">
                  {mediaBlock.content.mediaType === 'video' && (
                    <VideoAuthority 
                      metadata={{
                        _id: mediaBlock.content.mediaId,
                        provider: 'youtube',
                        title: mediaBlock.content.title || 'Video',
                        aspectRatio: (mediaBlock.content.aspectRatio as string) === 'vertical' ? 'vertical' : '16:9'
                      }}
                    />
                  )}
                  {mediaBlock.content.mediaType === '3d' && (
                    <ThreeDAuthority 
                      metadata={{
                        modelId: mediaBlock.content.mediaId,
                        modelUrl: mediaBlock.content.mediaId,
                        format: 'glb'
                      }}
                    />
                  )}
                  {mediaBlock.content.mediaType === 'drawing' && (
                    <TechnicalDrawingAuthority 
                      drawings={[{
                        _id: mediaBlock.id,
                        title: mediaBlock.content.title || 'Teknik Çizim',
                        url: mediaBlock.content.mediaId,
                        format: 'pdf',
                        category: 'dimensions'
                      }]}
                    />
                  )}
                  {mediaBlock.content.mediaType === 'image' && (
                    <img 
                      src={mediaBlock.content.mediaId} 
                      alt={mediaBlock.content.title || ''} 
                      className="w-full h-full object-cover" 
                    />
                  )}
                </div>
                {mediaBlock.content.description && (
                  <p className="mt-4 text-slate-500 text-sm italic text-center">{mediaBlock.content.description}</p>
                )}
              </div>
            );
          }

          case 'rich-text': {
            const rtBlock = block as RichTextBlockType;
            return (
              <div 
                key={rtBlock.id} 
                className="max-w-4xl mx-auto py-16 px-6 prose prose-slate prose-lg md:prose-xl"
                dangerouslySetInnerHTML={{ __html: rtBlock.content.html }}
              />
            );
          }
          
          default:
            return (
              <div key={block.id} className="p-8 border-2 border-dashed border-red-100 text-red-300 text-xs text-center m-8 rounded-3xl">
                Bilinmeyen Blok Tipi: {block.type}
              </div>
            );
        }
      })}
    </div>
  );
};

'use client';

import React from 'react';
import { Grid, List } from 'lucide-react';
import ProductCard from '../ProductCard';
import { useI18n } from '../../i18n/I18nProvider';
import type { Product } from '../../lib/supabase';

interface ProductsGridProps {
  products: Product[];
  viewMode: 'grid' | 'list';
  loading?: boolean;
  onViewModeChange?: (mode: 'grid' | 'list') => void;
  onSortChange?: (sortBy: string) => void;
  sortBy?: string;
}

/**
 * @component ProductsGrid
 * @description Ürün listesini ızgara veya liste modunda görüntüleyen atomik bileşen.
 */
const ProductsGr_id: React.FC<ProductsGridProps> = ({ 
  products, 
  viewMode, 
  loading,
  onViewModeChange,
  onSortChange,
  sortBy = 'name'
}) => {
  const { t } = useI18n();

  return (
    <div className="space-y-8">
      {/* Toolbar */}
      <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 pb-6 border-b border-slate-100">
        <p className="text-sm font-medium text-slate-500">
          <span className="text-slate-900 font-bold">{products.length}</span> {t('category.productsCount') || 'ürün bulundu'}
        </p>
        
        <div className="flex items-center gap-6">
          {onViewModeChange && (
            <div className="flex bg-white p-1 rounded-xl border border-slate-200 shadow-sm">
              <button 
                onClick={() => onViewModeChange('grid')}
                className={`p-2 rounded-lg transition-all ${viewMode === 'grid' ? 'bg-primary-navy text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
                title={t('category.view.grid') || 'Izgara Görünümü'}
              >
                <Grid size={18} />
              </button>
              <button 
                onClick={() => onViewModeChange('list')}
                className={`p-2 rounded-lg transition-all ${viewMode === 'list' ? 'bg-primary-navy text-white shadow-md' : 'text-slate-400 hover:text-slate-600'}`}
                title={t('category.view.list') || 'Liste Görünümü'}
              >
                <List size={18} />
              </button>
            </div>
          )}

          {onSortChange && (
            <select 
              value={sortBy}
              onChange={(e) => onSortChange(e.target.value)}
              className="bg-white border-slate-200 rounded-xl text-sm font-bold text-slate-700 py-2.5 pl-4 pr-10 focus:ring-primary-ocean/20 transition-all shadow-sm"
              aria-label={t('category.sort.title') || 'Sıralama'}
            >
              <option value="name">{t('category.sort.name') || 'İsim'}</option>
              <option value="price-low">{t('category.sort.priceLow') || 'Düşük Fiyat'}</option>
              <option value="price-high">{t('category.sort.priceHigh') || 'Yüksek Fiyat'}</option>
            </select>
          )}
        </div>
      </div>

      {/* Grid/List Content */}
      <div className={viewMode === 'grid' 
        ? "grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-3 gap-8" 
        : "flex flex-col gap-6"
      }>
        {products.map(product => (
          <ProductCard 
